package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.StringEscapeUtils.escapeJava(String)
 */
public class StringEscapeUtils_escapeJava_TriageGen4Test {

    @Test
    public void testEscapeJava_NullInput() {
        // Testing null input behavior
        assertNull("Passing null should return null", StringEscapeUtils.escapeJava(null));
    }

    @Test
    public void testEscapeJava_EmptyString() {
        // Testing empty string
        assertEquals("", StringEscapeUtils.escapeJava(""));
    }

    @Test
    public void testEscapeJava_SimpleString() {
        // Testing normal alphanumeric string
        assertEquals("Hello123", StringEscapeUtils.escapeJava("Hello123"));
    }

    @Test
    public void testEscapeJava_SpecialCharacters() {
        // Testing common escape characters
        assertEquals("Line1\\nLine2", StringEscapeUtils.escapeJava("Line1\nLine2"));
        assertEquals("Tab\\tCharacter", StringEscapeUtils.escapeJava("Tab\tCharacter"));
        assertEquals("Backslash\\\\", StringEscapeUtils.escapeJava("Backslash\\"));
        assertEquals("DoubleQuote\\\"", StringEscapeUtils.escapeJava("DoubleQuote\""));
        assertEquals("SingleQuote\\'", StringEscapeUtils.escapeJava("SingleQuote'"));
    }

    @Test
    public void testEscapeJava_ControlCharacters() {
        // Testing non-printable control characters (ASCII < 32)
        // Carriage return \r -> \r
        assertEquals("CR\\r", StringEscapeUtils.escapeJava("\r"));
        // Backspace \b -> \b
        assertEquals("BS\\b", StringEscapeUtils.escapeJava("\b"));
        // Form feed \f -> \f
        assertEquals("FF\\f", StringEscapeUtils.escapeJava("\f"));
    }

    @Test
    public void testEscapeJava_UnicodeCharacters() {
        // Testing Unicode escape sequences
        // Space is normal, but let's test a non-ASCII character
        assertEquals("\\u00a9", StringEscapeUtils.escapeJava("©"));
        assertEquals("\\u1234", StringEscapeUtils.escapeJava("\u1234"));
    }

    @Test
    public void testEscapeJava_MixedContent() {
        // Testing a complex mix of all types
        String input = "Hello\nWorld! \"Quotes\" and \\Backslash\\ and \u2122";
        // \n -> \n
        // " -> \"
        // \ -> \\
        // ™ -> \u2122
        String expected = "Hello\\nWorld! \\\"Quotes\\\" and \\\\Backslash\\\\ and \\u2122";
        assertEquals(expected, StringEscapeUtils.escapeJava(input));
    }

    @Test
    public void testEscapeJava_RoundTrip() {
        // Testing if escape followed by unescape returns original
        String original = "Line\nTab\tQuote\"Slash\\Unicode\u2122";
        String escaped = StringEscapeUtils.escapeJava(original);
        String unescaped = StringEscapeUtils.unescapeJava(escaped);
        assertEquals(original, unescaped);
    }
}
